     CREATE TABLE usuarios (
       id TEXT PRIMARY KEY,
       nome TEXT NOT NULL,
       papel TEXT NOT NULL
     );

     CREATE TABLE salas (
       id TEXT PRIMARY KEY,
       nome TEXT NOT NULL,
       capacidade INTEGER NOT NULL
