     const existente = db
       .prepare('SELECT * FROM presencas WHERE encontroId = ? AND participanteId = ?')
       .get(encontro.id, participanteId);
     if (existente) return res.status(200).json(existente);

     const inscricao = db
       .prepare(
         `SELECT 1 FROM inscricoes
