     const inicioMs = Date.parse(encontro.inicio);
     const fimMs = Date.parse(encontro.fim);
     if (registradaMs < inicioMs - 15 * 60000 || registradaMs > fimMs + 2 * 60 * 60000) {
       return erro(res, 422, 'FORA_DA_JANELA');
